/** The layer manager (spec §25.4): the tree, and the operations on it. */

import {
  colourOf,
  describeLayerPlan,
  layerTree,
  type LayerTreeNode,
  type LineType,
  LINE_TYPE_LABEL,
  LINE_TYPES,
  lineTypeOf,
  lineWidthOf,
  listLayers,
  MAX_LINE_WIDTH,
  MIN_LINE_WIDTH,
  opacityOf,
  planDeleteLayer,
  planMergeLayers,
  planRenameLayer,
  planReorder,
  planSplitLayer,
  setAllHidden,
  setView as setLayerView,
  toggleIsolate,
} from '../../core/layers';
import { LAYER_COLORS } from '../../ui/preview';
import { type QueueItem, store } from '../../state/store';
import { collapsibleNote, editDialog, element, ghostButton } from '../dom';
import { host } from '../host';
import { datasetForTools, protectedFor, tableStateOf, truncationOf, viewOf } from './dataset';
import { pendingEditsPanel, queueEdit } from './edits';
import { ui } from '../ui-state';

export function layersTab(item: QueueItem): HTMLElement[] {
  const data = datasetForTools(item);
  if (data.layers.length === 0) {
    return [element('p', { class: 'muted', style: 'padding:16px', text: 'This file has no layers.' })];
  }

  const view = viewOf(item);
  const nodes: HTMLElement[] = [];
  const search = ui.layerSearch;

  // Toolbar -------------------------------------------------------------
  const bar = element('div', { class: 'lm__bar' });
  const searchBox = element('input', {
    class: 'input',
    type: 'search',
    placeholder: 'Search layers and folders…',
    value: search,
    'aria-label': 'Search layers',
  }) as HTMLInputElement;
  searchBox.addEventListener('input', () => {
    ui.layerSearch = searchBox.value;
    host.renderInspector();
  });
  bar.append(searchBox);

  bar.append(
    ghostButton('Show all', () => {
      const names = data.layers.map((layer: any) => layer.name);
      store.updateItem(item.id, { layerView: setAllHidden(view, names, false) });
      host.render();
    })
  );
  bar.append(
    ghostButton('Hide all', () => {
      const names = data.layers.map((layer: any) => layer.name);
      store.updateItem(item.id, { layerView: setAllHidden(view, names, true) });
      host.render();
    })
  );
  nodes.push(bar);

  // The single most important sentence on this panel — kept visible, with the
  // rest folded away: as a full block it was taller than the layer list itself.
  nodes.push(
    collapsibleNote(
      'info',
      'Visibility is a view setting. It does not change what is exported.',
      'Hiding a layer here only removes it from the canvas. Every layer is still written to the output file.',
      'To export a subset, tick the layers you want and use "Export selected" below.'
    )
  );

  const items = listLayers(data, view, search);
  if (items.length === 0) {
    nodes.push(element('p', { class: 'muted', style: 'padding:16px', text: `No layer matches "${search}".` }));
    return nodes;
  }

  const list = element('div', { class: 'lm' });
  for (const node of layerTree(items)) renderLayerNode(node, list, item, 0);
  nodes.push(list);

  // Operations ----------------------------------------------------------
  //
  // ONE LINE, NOT FIVE BUTTONS.
  //
  // Export, Merge, Rename, Split and Delete used to sit here as a block that
  // wrapped to three rows and stood disabled most of the time, because four of
  // the five need a selection — three rows of a narrow rail spent telling the
  // user what they could not do yet. Every one of them is now on the layer's
  // own right-click menu, where the action arrives already knowing what it
  // applies to, and renaming is a double-click on the name.
  //
  // What stays is the part a menu cannot do: say that the menu is there, and
  // report what is ticked. A context menu nobody discovers is a feature that
  // does not exist, so this line is the discovery — not a second copy of the
  // five actions.
  const selected = ui.layerSelection.filter((name) => data.layers.some((layer: any) => layer.name === name));
  const ops = element('div', { class: 'lm__ops' });
  ops.append(
    element('div', {
      class: 'lm__opsTitle',
      text: selected.length > 0 ? `${selected.length} selected` : 'Nothing ticked',
    })
  );
  ops.append(
    element('span', {
      class: 'small faint',
      text:
        selected.length > 1
          ? 'Right-click any ticked layer for export, merge and delete.'
          : 'Right-click a layer for its actions · double-click its name to rename.',
    })
  );
  nodes.push(ops);

  const pending = (item.edits ?? []).filter((command) => command.kind.startsWith('layer-'));
  if (pending.length > 0) nodes.push(pendingEditsPanel(item, pending));

  return nodes;
}

export function renderLayerNode(node: LayerTreeNode, into: HTMLElement, item: QueueItem, depth: number): void {
  const view = viewOf(item);

  if (!node.layer) {
    // A folder with no layer of its own — a KML folder level.
    into.append(
      element('div', { class: 'lm__folder', style: `padding-left:${depth * 16 + 8}px` }, [
        element('span', { class: 'lm__folderIcon', text: '▾' }),
        element('span', { text: node.name }),
      ])
    );
    for (const child of node.children) renderLayerNode(child, into, item, depth + 1);
    return;
  }

  const entry = node.layer;
  const row = element('div', {
    class: `lm__row${ui.layerSelection.includes(entry.name) ? ' lm__row--on' : ''}`,
    style: `padding-left:${depth * 16 + 8}px`,
  });

  // RIGHT-CLICK IS WHERE THE ACTIONS LIVE.
  //
  // Every one of these already existed as a `plan*` command — this is wiring,
  // not new machinery. What it replaces is a block of five buttons sitting
  // permanently below the list, greyed out most of the time because four of
  // them need a selection: three rows of the panel spent telling the user what
  // they could not do yet. Put on the layer itself, each action arrives already
  // knowing what it applies to.
  //
  // The button row stays, because a menu nobody right-clicks is a menu nobody
  // finds. This is the fast path, not the only one.
  row.addEventListener('contextmenu', (event) => {
    event.preventDefault();
    // Right-clicking a layer that is not ticked acts on THAT layer, which is
    // what every file manager does. Right-clicking one that is ticked acts on
    // the whole ticked set, so a menu cannot silently drop a multi-selection.
    const selection = ui.layerSelection.includes(entry.name) ? [...ui.layerSelection] : [entry.name];
    openLayerMenu(item, selection, entry.name, event as MouseEvent);
  });

  const tick = element('input', { type: 'checkbox', 'aria-label': `Select ${entry.name}` }) as HTMLInputElement;
  tick.checked = ui.layerSelection.includes(entry.name);
  tick.addEventListener('change', () => {
    ui.layerSelection = tick.checked
      ? [...ui.layerSelection, entry.name]
      : ui.layerSelection.filter((name) => name !== entry.name);
    host.renderInspector();
  });
  row.append(tick);

  // Visibility ----------------------------------------------------------
  const eye = element('button', {
    class: `lm__icon${entry.visible ? ' lm__icon--on' : ''}`,
    title: entry.visible ? 'Hide on the canvas (does not affect the export)' : 'Show on the canvas',
    'aria-label': `${entry.visible ? 'Hide' : 'Show'} ${entry.name}`,
    text: entry.visible ? '👁' : '⌀',
  });
  eye.addEventListener('click', () => {
    store.updateItem(item.id, { layerView: setLayerView(view, entry.name, { hidden: entry.visible }) });
    host.render();
  });
  row.append(eye);

  // Lock ----------------------------------------------------------------
  const lock = element('button', {
    class: `lm__icon${entry.locked ? ' lm__icon--on' : ''}`,
    title: entry.locked ? 'Locked — every edit refuses on this layer' : 'Lock this layer against edits',
    'aria-label': `${entry.locked ? 'Unlock' : 'Lock'} ${entry.name}`,
    text: entry.locked ? '🔒' : '🔓',
  });
  lock.addEventListener('click', () => {
    store.updateItem(item.id, { layerView: setLayerView(view, entry.name, { locked: !entry.locked }) });
    host.render();
  });
  row.append(lock);

  // Isolate -------------------------------------------------------------
  const isolate = element('button', {
    class: `lm__icon${view.isolated === entry.name ? ' lm__icon--on' : ''}`,
    title: 'Show only this layer, without losing what is hidden',
    'aria-label': `Isolate ${entry.name}`,
    text: '◎',
  });
  isolate.addEventListener('click', () => {
    store.updateItem(item.id, { layerView: toggleIsolate(view, entry.name) });
    host.render();
  });
  row.append(isolate);

  const meta = `${(truncationOf(item, entry.name)?.total ?? entry.featureCount ?? 0).toLocaleString()} · ${entry.geometryTypes.join(', ') || 'no geometry'} · ${entry.fieldCount ?? 0} field${entry.fieldCount === 1 ? '' : 's'}`;
  // Both lines are clipped to one line each in a narrow rail, so the full text
  // has to stay reachable somewhere: the title is that somewhere.
  const label = element('button', {
    class: 'lm__name',
    title: `${entry.name} — ${meta}\nClick to show in the attribute table; double-click the name to rename`,
  });
  const nameText = element('span', { class: 'lm__nameText', text: entry.name });
  // DOUBLE-CLICK THE NAME TO RENAME IT, in place.
  //
  // Renaming meant ticking the layer, finding "Rename…" among five buttons
  // below the list, and answering a dialog — three steps and a modal to change
  // a word. Every file manager and every GIS renames in place on a double
  // click, and the name is what the exported legend shows, so it gets edited
  // often. The dialog stays on the menu for anyone who looks there.
  nameText.addEventListener('dblclick', (event) => {
    event.preventDefault();
    event.stopPropagation();
    beginInlineRename(item, entry.name, nameText);
  });
  label.append(nameText);
  label.append(
    element('span', {
      class: 'lm__meta',
      // `?? 0` is load-bearing. This panel used to render only when the user
      // opened the Layers tab, by which time the dataset was always fully
      // inspected; it now renders in the left rail on EVERY render, including
      // the ones during inspection where a layer entry exists before its counts
      // do. `undefined.toLocaleString()` threw there, and the exception aborted
      // the whole render — which is why the canvas drew its grid and then no
      // data at all, and the inspector body came out empty.
      text: meta,
    })
  );
  // THE SINGLE CLICK HAS TO WAIT FOR THE SECOND ONE.
  //
  // Showing the layer in the attribute table re-renders the whole panel, which
  // throws this row away and builds a new one. The first click of a double
  // click did exactly that, so the second click landed on a DIFFERENT element
  // and the browser never paired them into a `dblclick` at all — double-click
  // to rename simply did nothing, with no error to explain it. Measured: the
  // inline input never appeared.
  //
  // So the single-click action is held for the length of a double click and
  // cancelled if a second click arrives. 250ms is the usual platform threshold
  // and is imperceptible for a click whose result is a panel changing.
  let pendingOpen: ReturnType<typeof setTimeout> | null = null;
  const cancelPendingOpen = (): void => {
    if (pendingOpen === null) return;
    clearTimeout(pendingOpen);
    pendingOpen = null;
  };
  label.addEventListener('click', () => {
    cancelPendingOpen();
    pendingOpen = setTimeout(() => {
      pendingOpen = null;
      store.updateItem(item.id, { table: { ...tableStateOf(item), layer: entry.name, selection: [] } });
      store.set({ inspectorTab: 'attributes' });
      host.render();
    }, 250);
  });
  nameText.addEventListener('dblclick', cancelPendingOpen);
  row.append(label);

  // The style controls go on their own line inside the row.
  //
  // They used to sit flat beside the name. In a 260px rail that made the row
  // wider than the rail, and the trailing ones (line type, rename, reorder)
  // were clipped off the edge — present in the DOM and unreachable. Letting the
  // row wrap instead squeezed the NAME to nothing, because it was the only
  // flexible item. A sub-row that takes the full width fixes both: the name
  // keeps line one, the controls get line two, and nothing is cut off.
  const tools = element('div', { class: 'lm__tools' });

  // Opacity -------------------------------------------------------------
  const opacity = element('input', {
    class: 'lm__opacity',
    type: 'range',
    min: '0',
    max: '100',
    value: String(Math.round(opacityOf(view, entry.name) * 100)),
    title: 'Opacity on the canvas',
    'aria-label': `Opacity of ${entry.name}`,
  }) as HTMLInputElement;
  opacity.addEventListener('input', () => {
    store.updateItem(item.id, {
      layerView: setLayerView(view, entry.name, { opacity: Number(opacity.value) / 100 }),
    });
    host.render();
  });
  tools.append(opacity);

  // Style ----------------------------------------------------------------
  // A colour well, a width and a line type, right on the row: these are read
  // together — "the dashed red 2 px one" — and splitting them across a dialog
  // makes styling a dozen layers a dozen dialogs.
  const swatchIndex = indexOfLayer(item, entry.name);
  const colour = element('input', {
    class: 'lm__colour',
    type: 'color',
    value: colourOf(view, entry.name) ?? LAYER_COLORS[swatchIndex % LAYER_COLORS.length],
    title: 'Colour on the canvas, and in the exported legend',
    'aria-label': `Colour of ${entry.name}`,
  }) as HTMLInputElement;
  colour.addEventListener('input', () => {
    store.updateItem(item.id, { layerView: setLayerView(view, entry.name, { colour: colour.value }) });
    host.render();
  });
  tools.append(colour);

  const width = element('input', {
    class: 'lm__width',
    type: 'number',
    min: String(MIN_LINE_WIDTH),
    max: String(MAX_LINE_WIDTH),
    step: '0.5',
    value: String(lineWidthOf(view, entry.name)),
    title: 'Line thickness in pixels',
    'aria-label': `Line thickness of ${entry.name}`,
  }) as HTMLInputElement;
  width.addEventListener('change', () => {
    store.updateItem(item.id, { layerView: setLayerView(view, entry.name, { lineWidth: Number(width.value) }) });
    host.render();
  });
  tools.append(width);

  const lineType = element('select', {
    class: 'lm__lineType',
    title: 'Line type — dashed and dash-dot carry meaning on a survey sheet',
    'aria-label': `Line type of ${entry.name}`,
  }) as HTMLSelectElement;
  const currentType = lineTypeOf(view, entry.name);
  for (const type of LINE_TYPES) {
    const option = element('option', { value: type, text: LINE_TYPE_LABEL[type] });
    if (type === currentType) option.setAttribute('selected', 'selected');
    lineType.append(option);
  }
  lineType.addEventListener('change', () => {
    store.updateItem(item.id, {
      layerView: setLayerView(view, entry.name, { lineType: lineType.value as LineType }),
    });
    host.render();
  });
  tools.append(lineType);

  // Rename ---------------------------------------------------------------
  // `planRenameLayer` has existed since the layer manager shipped and was only
  // reachable from the multi-select toolbar, which meant renaming one layer
  // took two clicks in a different part of the panel.
  const rename = element('button', {
    class: 'lm__icon',
    title: 'Rename this layer — the name is what the exported legend shows',
    'aria-label': `Rename ${entry.name}`,
    text: '✎',
  });
  rename.addEventListener('click', () => promptRenameLayer(item, entry.name));
  tools.append(rename);

  // Reorder ---------------------------------------------------------------
  // `planReorder` also shipped with the layer manager and NOTHING constructed
  // its command, so layer order could not be changed at all. Order is not
  // cosmetic here: it decides draw order on the canvas, the order of the
  // folders an output tree gets under R16, and the order of the legend.
  const position = indexOfLayer(item, entry.name);
  const total = (item.dataset?.layers ?? []).length;

  const up = element('button', {
    class: 'lm__icon',
    title: 'Move this layer earlier — drawn first, so later layers sit on top of it',
    'aria-label': `Move ${entry.name} earlier`,
    text: '▲',
  }) as HTMLButtonElement;
  up.disabled = position <= 0;
  up.addEventListener('click', () => reorderLayer(item, entry.name, position - 1));
  tools.append(up);

  const down = element('button', {
    class: 'lm__icon',
    title: 'Move this layer later — drawn last, so it sits on top of the others',
    'aria-label': `Move ${entry.name} later`,
    text: '▼',
  }) as HTMLButtonElement;
  down.disabled = position >= total - 1;
  down.addEventListener('click', () => reorderLayer(item, entry.name, position + 1));
  tools.append(down);
  row.append(tools);

  into.append(row);
  for (const child of node.children) renderLayerNode(child, into, item, depth + 1);
}

/** Moves a layer to a new position, as a replayable command. */
function reorderLayer(item: QueueItem, name: string, toIndex: number): void {
  const data = datasetForTools(item);
  const plan = planReorder(data, name, toIndex);
  queueEdit(item, { kind: 'layer-reorder', layer: name, toIndex }, plan, describeLayerPlan(plan));
}

/** A layer's position in the dataset, which is what picks its default colour. */
function indexOfLayer(item: QueueItem, name: string): number {
  const index = (item.dataset?.layers ?? []).findIndex((layer: any) => layer.name === name);
  return index < 0 ? 0 : index;
}

/**
 * Renames a layer in place, on the row, without a dialog.
 *
 * Goes through exactly the same `planRenameLayer` gate as the dialog does —
 * protected layers, name clashes and empty names are refused by the planner,
 * not by this function — so the two routes cannot disagree about what is
 * allowed. The only difference is where the user types.
 */
export function beginInlineRename(item: QueueItem, layerName: string, into: HTMLElement): void {
  if (into.querySelector('input')) return; // already editing

  const input = element('input', {
    class: 'lm__rename',
    type: 'text',
    value: layerName,
    'aria-label': `Rename ${layerName}`,
  }) as HTMLInputElement;

  let settled = false;
  const finish = (commit: boolean): void => {
    if (settled) return;
    settled = true;
    const next = input.value.trim();
    // Escape, an empty name, or the name it already had: put the row back and
    // change nothing. Renaming a layer to itself should not enter the history.
    if (!commit || next === '' || next === layerName) {
      host.renderInspector();
      return;
    }
    const data = datasetForTools(item);
    const plan = planRenameLayer(data, layerName, next, { protectedLayers: protectedFor(item) });
    queueEdit(item, { kind: 'layer-rename', layer: layerName, to: next }, plan, describeLayerPlan(plan));
    if (!plan.refusal) ui.layerSelection = ui.layerSelection.map((name) => (name === layerName ? next : name));
    host.renderInspector();
  };

  input.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') finish(true);
    else if (event.key === 'Escape') finish(false);
    // The row is inside a button; without this, typing a space would press it.
    event.stopPropagation();
  });
  input.addEventListener('blur', () => finish(true));
  input.addEventListener('click', (event) => event.stopPropagation());
  input.addEventListener('dblclick', (event) => event.stopPropagation());

  into.replaceChildren(input);
  input.focus();
  input.select();
}

/**
 * The right-click menu for a layer.
 *
 * Built from the same `prompt*` functions the button row calls, so there is one
 * implementation of each action and the menu cannot drift from the buttons.
 * Items that cannot apply to this selection are shown disabled rather than
 * hidden: a menu whose shape changes is a menu you have to read every time.
 */
export function openLayerMenu(item: QueueItem, selection: string[], layerName: string, event: MouseEvent): void {
  document.querySelector('.ctxmenu')?.remove();

  const menu = element('div', { class: 'ctxmenu', role: 'menu' });
  const add = (label: string, enabled: boolean, run: () => void, hint?: string): void => {
    const node = element('button', {
      class: `ctxmenu__item${enabled ? '' : ' ctxmenu__item--off'}`,
      type: 'button',
      role: 'menuitem',
      ...(hint ? { title: hint } : {}),
    }) as HTMLButtonElement;
    node.textContent = label;
    node.disabled = !enabled;
    node.addEventListener('click', () => {
      menu.remove();
      run();
    });
    menu.append(node);
  };

  const one = selection.length === 1;
  add('Rename…', one, () => promptRenameLayer(item, selection[0]), 'Or double-click the name on the row');
  add(`Export ${selection.length > 1 ? `${selection.length} layers` : 'this layer'}…`, selection.length > 0, () =>
    exportSelectedLayers(item, selection)
  );
  // "Merge 1 layers…" is what counting without checking produces. The count is
  // only worth showing once there is actually a set to merge.
  add(
    selection.length >= 2 ? `Merge ${selection.length} layers…` : 'Merge…',
    selection.length >= 2,
    () => promptMergeLayers(item, selection),
    'Tick two or more layers to merge them'
  );
  add('Split…', one, () => promptSplitLayer(item, selection[0]), 'Split one layer by an attribute or by geometry type');
  menu.append(element('div', { class: 'ctxmenu__rule' }));
  add('Delete', one, () => promptDeleteLayer(item, selection[0]));

  // Positioned at the pointer, then nudged back inside the window: a menu
  // opened near the right or bottom edge would otherwise run off it.
  menu.style.left = `${event.clientX}px`;
  menu.style.top = `${event.clientY}px`;
  document.body.append(menu);
  const box = menu.getBoundingClientRect();
  if (box.right > window.innerWidth) menu.style.left = `${Math.max(4, window.innerWidth - box.width - 4)}px`;
  if (box.bottom > window.innerHeight) menu.style.top = `${Math.max(4, window.innerHeight - box.height - 4)}px`;

  const dismiss = (e: Event): void => {
    if (e.type === 'keydown' && (e as KeyboardEvent).key !== 'Escape') return;
    menu.remove();
    document.removeEventListener('pointerdown', dismiss, true);
    document.removeEventListener('keydown', dismiss, true);
  };
  // Deferred a tick: the pointerup of the right-click that opened this would
  // otherwise dismiss it immediately.
  setTimeout(() => {
    document.addEventListener('pointerdown', dismiss, true);
    document.addEventListener('keydown', dismiss, true);
  }, 0);
  void layerName;
}

export function promptRenameLayer(item: QueueItem, layerName: string): void {
  const data = datasetForTools(item);

  editDialog(
    `Rename "${layerName}"`,
    [{ key: 'name', label: 'New name', value: layerName }],
    (values) => {
      const plan = planRenameLayer(data, layerName, values.name, { protectedLayers: protectedFor(item) });
      return { text: describeLayerPlan(plan), blocked: plan.refusal !== undefined };
    },
    (values) => {
      const plan = planRenameLayer(data, layerName, values.name, { protectedLayers: protectedFor(item) });
      queueEdit(item, { kind: 'layer-rename', layer: layerName, to: values.name }, plan, describeLayerPlan(plan));
      ui.layerSelection = ui.layerSelection.map((name) => (name === layerName ? values.name : name));
    },
    'Rename'
  );
}

export function promptMergeLayers(item: QueueItem, names: string[]): void {
  const data = datasetForTools(item);

  editDialog(
    `Merge ${names.length} layers`,
    [{ key: 'name', label: 'Name for the merged layer', value: names[0] }],
    (values) => {
      const plan = planMergeLayers(data, names, values.name, { protectedLayers: protectedFor(item) });
      return { text: describeLayerPlan(plan), blocked: plan.refusal !== undefined };
    },
    (values) => {
      const plan = planMergeLayers(data, names, values.name, { protectedLayers: protectedFor(item) });
      queueEdit(item, { kind: 'layer-merge', layers: names, into: values.name }, plan, describeLayerPlan(plan));
      ui.layerSelection = [values.name];
    },
    'Merge'
  );
}

export function promptSplitLayer(item: QueueItem, layerName: string): void {
  const data = datasetForTools(item);
  const layer = data.layers.find((candidate: any) => candidate.name === layerName);
  if (!layer) return;

  const options = [
    { value: '__geometry__', label: 'geometry type' },
    ...layer.fields.map((field: any) => ({ value: field.name, label: `field "${field.name}"` })),
  ];

  const by = (value: string) => (value === '__geometry__' ? ({ kind: 'geometry' } as const) : ({ kind: 'field', field: value } as const));

  editDialog(
    `Split "${layerName}"`,
    [
      {
        key: 'by',
        label: 'Split by',
        kind: 'select',
        value: '__geometry__',
        options,
        hint: 'A field with a distinct value per feature would produce one layer per feature, and is refused.',
      },
    ],
    (values) => {
      const plan = planSplitLayer(data, layerName, by(values.by), { protectedLayers: protectedFor(item) });
      return { text: describeLayerPlan(plan), blocked: plan.refusal !== undefined };
    },
    (values) => {
      const plan = planSplitLayer(data, layerName, by(values.by), { protectedLayers: protectedFor(item) });
      queueEdit(item, { kind: 'layer-split', layer: layerName, by: by(values.by) }, plan, describeLayerPlan(plan));
      ui.layerSelection = [];
    },
    'Split'
  );
}

export function promptDeleteLayer(item: QueueItem, layerName: string): void {
  const data = datasetForTools(item);

  editDialog(
    `Delete "${layerName}"`,
    [],
    () => {
      const plan = planDeleteLayer(data, layerName, { protectedLayers: protectedFor(item) });
      return { text: describeLayerPlan(plan), blocked: plan.refusal !== undefined };
    },
    () => {
      const plan = planDeleteLayer(data, layerName, { protectedLayers: protectedFor(item) });
      queueEdit(item, { kind: 'layer-delete', layer: layerName }, plan, describeLayerPlan(plan));
      ui.layerSelection = ui.layerSelection.filter((name) => name !== layerName);
    },
    'Delete'
  );
}

/**
 * Exports only the selected layers, by queuing deletions for the rest.
 *
 * Expressed as edits rather than as a special export path, so the subset is
 * visible in the pending-edits list, reversible like any other edit, and
 * applied by the same replay against the full file. A separate "export subset"
 * flag would be a second way to decide what gets written, and the two would
 * eventually disagree.
 */
export function exportSelectedLayers(item: QueueItem, selected: string[]): void {
  const data = datasetForTools(item);
  const dropped = data.layers.map((layer: any) => layer.name).filter((name: string) => !selected.includes(name));

  if (dropped.length === 0) {
    store.log('warn', 'Every layer is already selected — nothing would be excluded.');
    host.render();
    return;
  }

  editDialog(
    'Export only the selected layers',
    [],
    () => ({
      text: `Keeps ${selected.join(', ')}. Removes ${dropped.join(', ')} from the output. This is queued as ${dropped.length} deletion(s) you can undo, not a hidden export setting.`,
      blocked: false,
    }),
    () => {
      let working = item;
      for (const name of dropped) {
        const plan = planDeleteLayer(datasetForTools(working), name, { protectedLayers: protectedFor(working) });
        if (plan.refusal) {
          store.log('warn', `${plan.refusal.what} ${plan.refusal.why}`);
          break;
        }
        queueEdit(working, { kind: 'layer-delete', layer: name }, plan, describeLayerPlan(plan));
        working = store.selected() ?? working;
      }
    },
    'Keep only these'
  );
}
