/**
 * Interactive geometry repair (spec §24), made reachable.
 *
 * ---------------------------------------------------------------------------
 * WHY THIS PANEL HAD TO EXIST
 *
 * `qa/repair.ts` has carried the whole §24.1 contract since Phase 10 —
 * `planRepair` previews without touching anything, `applyRepair` returns a new
 * dataset plus an undo diff, protected layers are refused and counted. Nothing
 * in the workspace called any of it. The only repair a user could reach was the
 * four checkboxes in Settings, which are conversion SETTINGS: they run inside
 * `qa/topology.ts` on the way through the pipeline, with no preview, no
 * per-layer scope and no undo.
 *
 * §24.1 opens by saying that shape is the wrong one for editing, which is the
 * entire reason `qa/repair.ts` was written. So the engine implementing the
 * right shape sat complete and unreachable, and the wrong shape was the only
 * one shipped — the same defect this codebase has hit before with the world
 * file writer and the shapefile ZIP writer: a finished engine with no caller.
 *
 * ---------------------------------------------------------------------------
 * WHY A PREVIEW COUNT IS NOT ENOUGH, AND WHAT IS SHOWN INSTEAD
 *
 * "142 rings closed" is the same sentence whether the repair fixed digitising
 * slips or dragged a boundary across a road. So the plan lists its largest
 * displacement in the data's own units (R21) and the first few individual
 * changes with their positions, and the Apply button carries that number. A
 * repair that moves nothing says so; one that moves 4.2 m says that instead.
 *
 * ---------------------------------------------------------------------------
 * WHY IT QUEUES AN EDIT RATHER THAN APPLYING IMMEDIATELY
 *
 * Same reason the geometry tools do. The preview holds at most a few thousand
 * features, so a plan computed here is a plan over a sample. Queuing a
 * `repair` command means the operation is RE-PLANNED at conversion time
 * against the whole dataset, lands in the history, and replays inside a
 * workflow. Applying to the preview only would produce a file that matches
 * what was on screen and not what was asked for.
 */

import {
  DEFAULT_REPAIR_SETTINGS,
  planRepair,
  REPAIR_LABEL,
  SAFE_OPERATIONS,
  type RepairOperationId,
  type RepairPlan,
} from '../../qa/repair';
import { crsLabel } from '../../crs/transform';
import type { QueueItem } from '../../state/store';
import { element, ghostButton, messageBlock } from '../dom';
import { host } from '../host';
import { datasetForTools, protectedFor, truncationOf } from './dataset';
import { pendingEditsPanel, queueEdit } from './edits';

/** Grouped the way someone looks for them, not the way they were implemented. */
const GROUPS: { label: string; operations: RepairOperationId[] }[] = [
  {
    label: 'Fix defects',
    operations: ['close-rings', 'remove-duplicate-vertices', 'remove-zero-length-segments', 'fix-ring-orientation', 'remove-spikes'],
  },
  { label: 'Reshape', operations: ['simplify', 'densify', 'smooth', 'regularise'] },
  { label: 'Holes', operations: ['remove-holes', 'fill-holes'] },
  { label: 'Snap', operations: ['snap-vertices'] },
  // Its own group rather than sitting under "Fix defects", because unlike the
  // five there it can change how many polygons a feature has — and in one mode
  // it removes area. That deserves to be looked for, not stumbled on.
  { label: 'Self-intersection', operations: ['repair-self-intersection'] },
  // Listed last and named for what they read, because these are the only ones
  // whose answer depends on a NEIGHBOUR — and the only one that deletes a
  // feature is in here.
  {
    label: 'Between features',
    operations: [
      'snap-shared-edges',
      'rebuild-topology',
      'merge-adjacent-polygons',
      'remove-slivers',
      'extend-trim-lines',
    ],
  },
];

/** What each one is for, in the terms the person choosing it is thinking in. */
const HINT: Record<RepairOperationId, string> = {
  'close-rings': 'Moves the last vertex of an open ring onto the first. The gap is reported before anything moves.',
  'remove-duplicate-vertices': 'Collapses vertices that sit within the tolerance of each other. No position moves.',
  'remove-zero-length-segments': 'Removes exactly coincident consecutive vertices. No position moves.',
  'fix-ring-orientation': 'Exterior rings counter-clockwise, holes clockwise (RFC 7946). Vertices keep their positions.',
  'remove-spikes': 'Removes vertices where the boundary doubles back on itself below the spike angle.',
  simplify: 'Douglas-Peucker. Drops vertices that lie within the band of the line replacing them — the band is the largest the boundary can shift.',
  densify: 'Adds vertices so no segment is longer than the maximum. Every original position is kept and nothing moves.',
  smooth: 'Chaikin corner cutting. This MOVES the boundary and is a cartographic choice, not a fix.',
  regularise: 'Pulls near-square corners to right angles, in the frame of the shape\'s own longest edge rather than the grid\'s.',
  'remove-holes': 'Removes holes at or under the area given, which is usually digitising noise. Larger holes are kept.',
  'fill-holes': 'Removes every hole regardless of size. The exterior boundary does not move.',
  'snap-vertices': 'Collapses vertices within the tolerance onto the first of the group. Snapping moves survey positions.',
  'snap-shared-edges':
    'Collapses vertices of DIFFERENT features onto one shared node — the gap between two parcels digitised from separate sheets. Each node moves to the mean of its cluster, so the correction is shared rather than one parcel being made authoritative by file order.',
  'rebuild-topology':
    'Snaps shared nodes, then inserts a vertex wherever a neighbour\'s corner sits on the middle of this boundary. That second half is what snapping cannot reach: the positions already agree, but without the node every later overlay leaves a sliver.',
  'merge-adjacent-polygons':
    'Unions polygons that share an edge. This DELETES features: one survives per group and keeps its attributes, the rest are removed and theirs go with them.',
  'repair-self-intersection':
    'Cuts a ring that crosses itself at the crossing. A bowtie encloses no well-defined area — the shoelace sum counts one lobe against the other — so writers and boolean operations are entitled to assume it does not happen. Choose whether to keep every lobe or only the largest.',
  'remove-slivers':
    'Deletes polygons that are both thin AND small — the shaving left where two surveys of one boundary disagree by centimetres. This DELETES features, with their attributes. A road reserve is thin but not small, and a garden plot is small but not thin; neither is touched.',
  'extend-trim-lines':
    'Closes undershoots and cuts overshoots at line junctions. An end that stops short is extended ALONG ITS OWN BEARING to the line it was reaching for — not moved sideways onto it, which would bend the line. An end that runs past is cut back to the crossing. Ends already connected, and ends with nothing within reach, are left alone.',
};

const NEEDS_TOLERANCE = new Set<RepairOperationId>([
  'remove-duplicate-vertices',
  'snap-vertices',
  // Reads it as the "is this end already ON the line" test, which is what
  // decides an end is connected and must be left alone.
  'extend-trim-lines',
]);
const NEEDS_SHARED_TOLERANCE = new Set<RepairOperationId>([
  'snap-shared-edges',
  'rebuild-topology',
  'merge-adjacent-polygons',
]);

interface PanelState {
  itemId: string | null;
  layer: string;
  operation: RepairOperationId;
  tolerance: string;
  simplifyTolerance: string;
  densifyMaxSegment: string;
  smoothIterations: string;
  regulariseAngleDegrees: string;
  maxHoleArea: string;
  spikeAngleDegrees: string;
  sharedEdgeTolerance: string;
  selfIntersectionMode: 'split' | 'largest';
  sliverThinnessThreshold: string;
  sliverMaxArea: string;
  danglingTolerance: string;
}

const ALL_LAYERS = '�all';

const panel: PanelState = {
  itemId: null,
  layer: ALL_LAYERS,
  operation: 'close-rings',
  tolerance: String(DEFAULT_REPAIR_SETTINGS.tolerance),
  simplifyTolerance: String(DEFAULT_REPAIR_SETTINGS.simplifyTolerance),
  densifyMaxSegment: String(DEFAULT_REPAIR_SETTINGS.densifyMaxSegment),
  smoothIterations: String(DEFAULT_REPAIR_SETTINGS.smoothIterations),
  regulariseAngleDegrees: String(DEFAULT_REPAIR_SETTINGS.regulariseAngleDegrees),
  maxHoleArea: String(DEFAULT_REPAIR_SETTINGS.maxHoleArea),
  spikeAngleDegrees: String(DEFAULT_REPAIR_SETTINGS.spikeAngleDegrees),
  sharedEdgeTolerance: String(DEFAULT_REPAIR_SETTINGS.sharedEdgeTolerance),
  selfIntersectionMode: DEFAULT_REPAIR_SETTINGS.selfIntersectionMode,
  sliverThinnessThreshold: String(DEFAULT_REPAIR_SETTINGS.sliverThinnessThreshold),
  sliverMaxArea: String(DEFAULT_REPAIR_SETTINGS.sliverMaxArea),
  danglingTolerance: String(DEFAULT_REPAIR_SETTINGS.danglingTolerance),
};

function reset(item: QueueItem): void {
  panel.itemId = item.id;
  panel.layer = ALL_LAYERS;
}

function numberOr(text: string, fallback: number): number {
  const value = Number(text);
  return Number.isFinite(value) ? value : fallback;
}

/** The settings the current operation actually reads, so the plan matches the form. */
function optionsFromPanel(): Record<string, number | string> {
  return {
    selfIntersectionMode: panel.selfIntersectionMode,
    sliverThinnessThreshold: numberOr(panel.sliverThinnessThreshold, DEFAULT_REPAIR_SETTINGS.sliverThinnessThreshold),
    sliverMaxArea: numberOr(panel.sliverMaxArea, DEFAULT_REPAIR_SETTINGS.sliverMaxArea),
    danglingTolerance: numberOr(panel.danglingTolerance, DEFAULT_REPAIR_SETTINGS.danglingTolerance),
    tolerance: numberOr(panel.tolerance, DEFAULT_REPAIR_SETTINGS.tolerance),
    spikeAngleDegrees: numberOr(panel.spikeAngleDegrees, DEFAULT_REPAIR_SETTINGS.spikeAngleDegrees),
    simplifyTolerance: numberOr(panel.simplifyTolerance, DEFAULT_REPAIR_SETTINGS.simplifyTolerance),
    densifyMaxSegment: numberOr(panel.densifyMaxSegment, DEFAULT_REPAIR_SETTINGS.densifyMaxSegment),
    smoothIterations: Math.max(1, Math.round(numberOr(panel.smoothIterations, DEFAULT_REPAIR_SETTINGS.smoothIterations))),
    regulariseAngleDegrees: numberOr(panel.regulariseAngleDegrees, DEFAULT_REPAIR_SETTINGS.regulariseAngleDegrees),
    maxHoleArea: numberOr(panel.maxHoleArea, DEFAULT_REPAIR_SETTINGS.maxHoleArea),
    sharedEdgeTolerance: numberOr(panel.sharedEdgeTolerance, DEFAULT_REPAIR_SETTINGS.sharedEdgeTolerance),
  };
}

function labelled(label: string, control: HTMLElement, hint?: string): HTMLElement {
  const wrap = element('label', { class: 'field' });
  wrap.append(element('span', { class: 'field__label', text: label }));
  wrap.append(control);
  if (hint) wrap.append(element('span', { class: 'small faint', text: hint }));
  return wrap;
}

function numberInput(value: string, onChange: (next: string) => void): HTMLInputElement {
  const field = element('input', { class: 'input', type: 'text', value }) as HTMLInputElement;
  field.addEventListener('change', () => onChange(field.value));
  return field;
}

export function repairTab(item: QueueItem): HTMLElement[] {
  const data = datasetForTools(item);
  const layerNames: string[] = data.layers.map((layer: any) => layer.name);

  if (layerNames.length === 0) {
    return [element('p', { class: 'muted', style: 'padding:16px', text: 'This file has no layers to repair.' })];
  }
  if (panel.itemId !== item.id) reset(item);
  if (panel.layer !== ALL_LAYERS && !layerNames.includes(panel.layer)) panel.layer = ALL_LAYERS;

  const nodes: HTMLElement[] = [];
  const form = element('div', { class: 'stack', style: 'padding:12px' });

  form.append(
    element('p', {
      class: 'small muted',
      text: 'Repair edits geometry. Nothing changes until you apply, and every change is listed first with the distance it moves.',
    })
  );

  // --- scope -------------------------------------------------------------
  const layerSelect = element('select', { class: 'select', 'aria-label': 'Layer' }) as HTMLSelectElement;
  const everyOption = element('option', { value: ALL_LAYERS, text: 'Every layer' });
  if (panel.layer === ALL_LAYERS) everyOption.setAttribute('selected', 'selected');
  layerSelect.append(everyOption);
  for (const name of layerNames) {
    const option = element('option', { value: name, text: name });
    if (name === panel.layer) option.setAttribute('selected', 'selected');
    layerSelect.append(option);
  }
  layerSelect.addEventListener('change', () => {
    panel.layer = layerSelect.value;
    host.renderInspector();
  });
  form.append(labelled('Layer', layerSelect));

  // --- operation ---------------------------------------------------------
  const operationSelect = element('select', { class: 'select', 'aria-label': 'Operation' }) as HTMLSelectElement;
  for (const group of GROUPS) {
    const optgroup = element('optgroup') as HTMLOptGroupElement;
    optgroup.label = group.label;
    for (const operation of group.operations) {
      const option = element('option', { value: operation, text: REPAIR_LABEL[operation] });
      if (operation === panel.operation) option.setAttribute('selected', 'selected');
      optgroup.append(option);
    }
    operationSelect.append(optgroup);
  }
  operationSelect.addEventListener('change', () => {
    panel.operation = operationSelect.value as RepairOperationId;
    host.renderInspector();
  });
  form.append(labelled('Operation', operationSelect));
  form.append(element('p', { class: 'small muted', text: HINT[panel.operation] }));

  // --- parameters, only the ones this operation reads ---------------------
  const crs = item.dataset?.crs ?? null;
  const units = crs ? `In the units of ${crsLabel(crs)}.` : 'This dataset declares no CRS, so the number is in whatever units the file holds.';

  if (NEEDS_TOLERANCE.has(panel.operation)) {
    form.append(labelled('Tolerance', numberInput(panel.tolerance, (value) => { panel.tolerance = value; host.renderInspector(); }), units));
  }
  if (panel.operation === 'remove-spikes') {
    form.append(labelled('Spike angle (degrees)', numberInput(panel.spikeAngleDegrees, (value) => { panel.spikeAngleDegrees = value; host.renderInspector(); }), 'Interior angles below this count as a spike.'));
  }
  if (panel.operation === 'simplify') {
    form.append(labelled('Simplification band', numberInput(panel.simplifyTolerance, (value) => { panel.simplifyTolerance = value; host.renderInspector(); }), `${units} No vertex that stays will move; the boundary shifts by at most this.`));
  }
  if (panel.operation === 'densify') {
    form.append(labelled('Longest segment', numberInput(panel.densifyMaxSegment, (value) => { panel.densifyMaxSegment = value; host.renderInspector(); }), units));
  }
  if (panel.operation === 'smooth') {
    form.append(labelled('Passes', numberInput(panel.smoothIterations, (value) => { panel.smoothIterations = value; host.renderInspector(); }), 'Each pass replaces every corner with two points.'));
  }
  if (panel.operation === 'regularise') {
    form.append(labelled('Square within (degrees)', numberInput(panel.regulariseAngleDegrees, (value) => { panel.regulariseAngleDegrees = value; host.renderInspector(); }), 'Edges further than this from a right angle are left alone — a genuine diagonal is not an error.'));
  }
  if (NEEDS_SHARED_TOLERANCE.has(panel.operation)) {
    form.append(
      labelled(
        'Shared-node tolerance',
        numberInput(panel.sharedEdgeTolerance, (value) => {
          panel.sharedEdgeTolerance = value;
          host.renderInspector();
        }),
        `${units} Vertices of DIFFERENT features closer than this are treated as one node. Deliberately separate from the tolerance above, which asks whether two points inside ONE feature are the same.`
      )
    );
  }
  if (panel.operation === 'repair-self-intersection') {
    // A CHOICE, not a default the tool makes silently. A bowtie has two
    // defensible readings and only the person who knows the survey can say
    // which applies, so both are offered and neither is hidden.
    const mode = element('select', { class: 'select', 'aria-label': 'Resolution' }) as HTMLSelectElement;
    for (const [value, label] of [
      ['split', 'Keep every lobe, as separate polygons'],
      ['largest', 'Keep the largest lobe only'],
    ] as [PanelState['selfIntersectionMode'], string][]) {
      const option = element('option', { value, text: label });
      if (panel.selfIntersectionMode === value) option.setAttribute('selected', 'selected');
      mode.append(option);
    }
    mode.addEventListener('change', () => {
      panel.selfIntersectionMode = mode.value as PanelState['selfIntersectionMode'];
      host.renderInspector();
    });
    form.append(
      labelled(
        'Resolution',
        mode,
        panel.selfIntersectionMode === 'split'
          ? 'Nothing is lost: the ring is cut at the crossing and each lobe becomes its own polygon.'
          : 'The smaller lobes are DELETED, and the plan says how much area goes with them.'
      )
    );
  }
  if (panel.operation === 'remove-slivers') {
    form.append(
      labelled(
        'Thinness at or below',
        numberInput(panel.sliverThinnessThreshold, (value) => {
          panel.sliverThinnessThreshold = value;
          host.renderInspector();
        }),
        '4·π·area ÷ perimeter². A circle is 1, a square about 0.785, a 100 m × 2 cm shaving about 0.0008. The same measure the QA scan reports a sliver with.'
      )
    );
    form.append(
      labelled(
        'AND area under',
        numberInput(panel.sliverMaxArea, (value) => {
          panel.sliverMaxArea = value;
          host.renderInspector();
        }),
        `${units} Squared. Both tests must pass — a road reserve is thin but not small, a garden plot small but not thin, and neither is a sliver.`
      )
    );
  }
  if (panel.operation === 'extend-trim-lines') {
    form.append(
      labelled(
        'Reach for a junction',
        numberInput(panel.danglingTolerance, (value) => {
          panel.danglingTolerance = value;
          host.renderInspector();
        }),
        `${units} How far an end may be from the line it was meant to meet. Beyond this it is taken to be a real dangle, ending where it was drawn to end.`
      )
    );
  }
  if (panel.operation === 'remove-slivers') {
    form.append(
      messageBlock(
        'warn',
        'This removes features.',
        'A polygon that is thin AND small is deleted outright, with its attributes. A multipart polygon loses only the parts that qualify and survives.',
        'Undo restores them exactly, and the plan below lists every one with its area and thinness before anything is applied.'
      )
    );
  }
  if (panel.operation === 'merge-adjacent-polygons') {
    // The only operation in the panel that removes features. Saying so before
    // the plan is read is cheaper than saying it after the apply.
    form.append(
      messageBlock(
        'warn',
        'This removes features.',
        'One polygon survives per adjacent group and keeps its attributes; the others are deleted and theirs go with them.',
        'Undo restores them exactly, and the plan below lists every group before anything is applied.'
      )
    );
  }
  if (panel.operation === 'remove-holes') {
    form.append(labelled('Largest hole to remove (area)', numberInput(panel.maxHoleArea, (value) => { panel.maxHoleArea = value; host.renderInspector(); }), 'In the square of the units above.'));
  }

  nodes.push(form);

  // --- the plan ----------------------------------------------------------
  const scope = panel.layer === ALL_LAYERS ? {} : { layer: panel.layer };
  let plan: RepairPlan | null = null;
  let failure: string | null = null;
  try {
    plan = planRepair(data, panel.operation, scope, { ...optionsFromPanel(), protectedLayers: protectedFor(item) });
  } catch (error) {
    failure = error instanceof Error ? error.message : String(error);
  }

  const results = element('div', { class: 'stack', style: 'padding:0 12px 12px' });

  if (failure) {
    results.append(messageBlock('error', 'The repair could not be planned.', failure));
  } else if (plan) {
    for (const refusal of plan.refused) {
      results.append(
        messageBlock(
          'warn',
          `"${refusal.layer}" is protected — ${refusal.featureCount.toLocaleString()} feature${refusal.featureCount === 1 ? '' : 's'} left untouched.`,
          refusal.reason,
          'Remove it from the protected list in Settings if this edit is intended.'
        )
      );
    }

    if (plan.changes.length === 0) {
      results.append(
        element('p', {
          class: 'small muted',
          text:
            plan.refused.length > 0
              ? 'Nothing outside the protected layers needs this repair.'
              : `Nothing in scope needs "${REPAIR_LABEL[panel.operation]}".`,
        })
      );
    } else {
      const moves = plan.maxDisplacement > 0;
      results.append(
        element('p', {
          class: moves ? 'small warn' : 'small muted',
          text: moves
            ? `${plan.changes.length.toLocaleString()} change${plan.changes.length === 1 ? '' : 's'}; the largest moves a position ${plan.maxDisplacement.toFixed(4)} units.`
            : `${plan.changes.length.toLocaleString()} change${plan.changes.length === 1 ? '' : 's'}, none of which moves a position.`,
        })
      );

      // The first few, concretely. A count alone cannot distinguish a repair of
      // digitising slips from one dragging a boundary across a road.
      const list = element('ul', { class: 'small', style: 'margin:0;padding-left:18px' });
      for (const change of plan.changes.slice(0, 8)) {
        list.append(element('li', { text: `${change.layer}: ${change.description}` }));
      }
      if (plan.changes.length > 8) {
        list.append(element('li', { class: 'faint', text: `… and ${(plan.changes.length - 8).toLocaleString()} more.` }));
      }
      results.append(list);

      if (!SAFE_OPERATIONS.includes(panel.operation)) {
        results.append(
          element('p', {
            class: 'small faint',
            text: 'This operation is not part of "fix all safe issues": it either moves a boundary or changes area, so it is only ever applied deliberately.',
          })
        );
      }

      const truncation = panel.layer === ALL_LAYERS ? null : truncationOf(item, panel.layer);
      if (truncation) {
        results.append(
          element('p', {
            class: 'small faint',
            text: `Planned over the ${truncation.shown.toLocaleString()} features loaded for preview, of ${truncation.total.toLocaleString()}. The repair is re-planned against all of them when the file converts.`,
          })
        );
      }

      const apply = ghostButton(
        moves ? `Apply — moves up to ${plan.maxDisplacement.toFixed(4)} units` : 'Apply',
        () => {
          queueEdit(
            item,
            {
              kind: 'repair',
              ...(panel.layer === ALL_LAYERS ? {} : { layer: panel.layer }),
              operation: panel.operation,
              options: optionsFromPanel(),
            },
            { refusal: undefined },
            `${REPAIR_LABEL[panel.operation]} — ${panel.layer === ALL_LAYERS ? 'every layer' : `"${panel.layer}"`}`
          );
        }
      );
      results.append(apply);
    }
  }

  nodes.push(results);
  if ((item.edits ?? []).length > 0) nodes.push(pendingEditsPanel(item, item.edits ?? []));
  return nodes;
}
