/**
 * Where a drawing goes, and what it is called.
 *
 * Panel state rather than store state, like the geometry panel's: a
 * half-configured drawing target is not worth a store round trip per keystroke,
 * and it must not survive into a project file.
 */
const drawState = {
  itemId: null as string | null,
  /** Empty means a new layer, named below. */
  targetLayer: '',
  newLayerName: 'Drawn',
  /** For a marker or a text object. */
  label: '',
  snapVertex: true,
  snapMidpoint: false,
  snapSegment: false,
  /** Restrict snapping to imported POINT layers — phase K's digitising mode. */
  snapPointsOnly: false,
};

export function selectTab(item: QueueItem): HTMLElement[] {
  const layers = selectableLayers(item);
  if (layers.length === 0) {
    return [element('p', { class: 'muted', style: 'padding:16px', text: 'This file has no vector layers to select from.' })];
  }

  const nodes: HTMLElement[] = [];
  const wrap = element('div', { class: 'stack', style: 'padding:12px' });
  const selection = ui.featureSelection;

  // --- which tool is live -------------------------------------------------
  //
  // This panel used to carry its OWN row of Select/Lasso/Move, the five drawing
  // tools and Ortho — a second copy of buttons that now live on the canvas
  // toolbar. Two copies of one control is not merely clutter here: this row
  // called `ui.toolCanvas.setTool()` DIRECTLY, bypassing the store that
  // `setCanvasTool` writes and that the toolbar lights from. Picking a tool here
  // therefore armed it on the canvas while the toolbar went on showing the
  // previous one, and the two disagreed until something else forced a render.
  //
  // The toolbar is the only writer now. This panel reports the live tool and
  // holds the settings that have nowhere else to live (what a drawn feature is
  // added to, snapping targets, the selection itself).
  const live = ui.toolCanvas?.getTool() ?? 'select';
  wrap.append(
    element('p', {
      class: 'small faint',
      text: `${TOOL_LABEL[live]} — ${TOOL_HINT[live]}`,
    })
  );

  // --- drawing (phases F and K) -------------------------------------------
  if (kindOfTool(ui.toolCanvas?.getTool() ?? 'select')) {
    wrap.append(drawingSection(item, layers));
  }

  // --- what is selected ---------------------------------------------------
  const summary = element('div', { class: 'section' });
  summary.append(element('h3', { class: 'section__title', text: 'Selection' }));
  summary.append(element('p', { class: 'small', text: describeSelection(selection, layers) }));

  const actions = element('div', { class: 'row' });
  actions.append(
    ghostButton('Clear', () => {
      setSelection(EMPTY_SELECTION);
    })
  );
  actions.append(ghostButton('Zoom to selection', () => zoomToSelection()));
  summary.append(actions);
  wrap.append(summary);

  // --- what the clicked feature IS (phase E) -------------------------------
  const info = featureInfo(item, selection);
  if (info) wrap.append(info);

  for (const warning of truncationWarnings(selection, layers)) {
    wrap.append(messageBlock('warn', 'Part of a layer cannot be reached by hand.', warning, 'Take the whole layer below if you meant all of it.'));
  }

  // --- whole layers -------------------------------------------------------
  const whole = element('div', { class: 'section' });
  whole.append(element('h3', { class: 'section__title', text: 'Take a whole layer' }));
  whole.append(
    element('p', {
      class: 'small faint',
      text: 'A whole layer covers every feature, including the ones the canvas did not draw. A canvas gesture can only reach what is drawn.',
    })
  );
  for (const layer of layers) {
    const line = element('label', { class: 'check' });
    const box = element('input', { type: 'checkbox' }) as HTMLInputElement;
    box.checked = selection.wholeLayers.includes(layer.name);
    box.disabled = layer.locked === true;
    box.addEventListener('change', () => setSelection(toggleWholeLayer(ui.featureSelection, layer.name)));
    line.append(box);
    line.append(
      element('span', {
        text: `${layer.name} — ${(layer.featureCount ?? layer.features.length).toLocaleString()} features${layer.locked ? ' (locked)' : ''}${layer.visible === false ? ' (hidden)' : ''}`,
      })
    );
    whole.append(line);
  }
  wrap.append(whole);

  // --- the shift warning, next to the control that causes it --------------
  wrap.append(
    messageBlock(
      'info',
      'A shift against a basemap has three possible causes, and dragging fixes one.',
      'A wrong or missing datum shift — fix the CRS instead. An old local grid with no relationship to WGS 84 — dragging is right. Or a basemap that is simply imprecise — the survey is right and moving it makes it wrong.',
      'Whatever you apply is recorded with its offset, so the decision can be checked later.'
    )
  );

  const crs = item.dataset?.crs ?? null;
  wrap.append(
    element('p', {
      class: 'small faint',
      text: crs
        ? `Offsets are in the units of ${crsLabel(crs)}.`
        : 'This dataset declares no CRS, so a distance dragged here has no stated unit. Set one in the CRS tab.',
    })
  );

  nodes.push(wrap);
  if ((item.edits ?? []).length > 0) nodes.push(pendingEditsPanel(item, item.edits ?? []));
  return nodes;
}

/**
 * Where a drawing lands, and what it snaps to.
 *
 * The snap settings are the phase-K feature in disguise. "Digitise a CSV" is
 * this panel with vertex snapping on and the sources narrowed to the imported
 * point layers: click each observed point in order, and every vertex is the
 * OBSERVED coordinate rather than one within a few pixels of it.
 *
 * Midpoint and segment snapping are off by default and stay off in that mode,
 * because neither is an observed position — a boundary running through the
 * midpoint between two control points is not the boundary that was surveyed,
 * and it would look completely deliberate.
 */
function drawingSection(item: QueueItem, layers: SelectableLayer[]): HTMLElement {
  if (drawState.itemId !== item.id) {
    drawState.itemId = item.id;
    drawState.targetLayer = '';
    drawState.label = '';
  }

  const tool = ui.toolCanvas?.getTool() ?? 'select';
  const kind = kindOfTool(tool);
  const section = element('div', { class: 'section' });
  section.append(element('h3', { class: 'section__title', text: 'Where it goes' }));

  const target = element('select', { class: 'select', 'aria-label': 'Layer to draw into' }) as HTMLSelectElement;
  target.append(element('option', { value: '', text: 'A new layer…' }));
  for (const layer of layers) {
    const option = element('option', { value: layer.name, text: `${layer.name}${layer.locked ? ' (locked)' : ''}` });
    if (layer.locked) option.setAttribute('disabled', 'disabled');
    target.append(option);
  }
  target.value = drawState.targetLayer;
  target.addEventListener('change', () => {
    drawState.targetLayer = target.value;
    host.renderInspector();
  });
  section.append(target);

  if (drawState.targetLayer === '') {
    const name = element('input', {
      class: 'input',
      type: 'text',
      value: drawState.newLayerName,
      'aria-label': 'Name for the new layer',
    }) as HTMLInputElement;
    name.addEventListener('change', () => {
      drawState.newLayerName = name.value.trim() || 'Drawn';
    });
    section.append(name);
  }

  if (kind === 'marker' || kind === 'text') {
    const label = element('input', {
      class: 'input',
      type: 'text',
      value: drawState.label,
      placeholder: kind === 'text' ? 'The text to place' : 'Marker name',
      'aria-label': kind === 'text' ? 'The text to place' : 'Marker name',
    }) as HTMLInputElement;
    label.addEventListener('input', () => {
      drawState.label = label.value;
    });
    section.append(label);
    if (kind === 'text') {
      section.append(
        element('p', {
          class: 'small faint',
          text: 'Written as a point carrying a "text" attribute. No vector GIS format has a text primitive that survives conversion, so font, height and rotation are not stored.',
        })
      );
    }
  }

  section.append(element('h3', { class: 'section__title', style: 'margin-top:12px', text: 'Snapping' }));
  section.append(
    check('Snap to existing vertices', drawState.snapVertex, (value) => {
      drawState.snapVertex = value;
    })
  );
  section.append(
    check('Snap to segment midpoints', drawState.snapMidpoint, (value) => {
      drawState.snapMidpoint = value;
    })
  );
  section.append(
    check('Snap anywhere along a segment', drawState.snapSegment, (value) => {
      drawState.snapSegment = value;
    })
  );
  section.append(
    check('Only snap to imported points (digitising a survey CSV)', drawState.snapPointsOnly, (value) => {
      drawState.snapPointsOnly = value;
      // Digitising means observed coordinates only, so the derived targets go
      // off with it rather than being left on to quietly beat a real point.
      if (value) {
        drawState.snapMidpoint = false;
        drawState.snapSegment = false;
        drawState.snapVertex = true;
      }
      host.renderInspector();
    })
  );
  section.append(
    element('p', {
      class: 'small faint',
      text: 'A snapped vertex is EXACTLY the stored coordinate, not one near it — snapping that rounds is worse than none, because it looks deliberate. Snapped vertices are drawn in blue so you can see which ones took.',
    })
  );

  const placed = ui.toolCanvas?.drawnCount() ?? 0;
  if (placed > 0 && kind) {
    const row = element('div', { class: 'row' });
    row.append(
      element('button', { class: 'btn btn--primary btn--sm', type: 'button', text: `Finish (${placed} placed)` })
    );
    (row.lastChild as HTMLElement).addEventListener('click', () => ui.toolCanvas?.finishDrawing());
    row.append(ghostButton('Cancel', () => {
      ui.toolCanvas?.cancelDrawing();
      host.renderInspector();
    }));
    section.append(row);
  }

  return section;
}

function check(text: string, value: boolean, onChange: (value: boolean) => void): HTMLElement {
  const line = element('label', { class: 'check' });
  const box = element('input', { type: 'checkbox' }) as HTMLInputElement;
  box.checked = value;
  box.addEventListener('change', () => onChange(box.checked));
  line.append(box, element('span', { text }));
  return line;
}

/**
 * Turns a finished drawing into a `draw` command.
 *
 * The refusals come from `buildDrawnFeature` rather than from here, so a
 * two-vertex polygon is rejected in one place whatever produced it.
 */
function commitDrawing(kind: DrawKind, positions: Position[], snaps: SnapTarget[]): void {
  const item = store.selected();
  if (!item) return;

  const built = buildDrawnFeature(kind, positions, {
    text: kind === 'text' ? drawState.label : undefined,
    name: kind === 'marker' ? drawState.label || undefined : undefined,
  });

  if (built.refusal) {
    store.log('warn', `${built.refusal.what} ${built.refusal.why} ${built.refusal.action}`);
    host.render();
    return;
  }
  if (!built.result) return;

  const layerName = drawState.targetLayer || drawState.newLayerName.trim() || 'Drawn';
  const command: EditCommand = {
    kind: 'draw',
    layer: layerName,
    features: [built.result.feature],
    createLayer: drawState.targetLayer === '',
  };

  queueEdit(item, command, {}, `Drew a ${DRAW_LABEL[kind].toLowerCase()} into ${layerName}`);

  for (const note of built.result.notes) store.log('info', note);
  if (snaps.length > 0) {
    store.log(
      'ok',
      `${snaps.length} of ${positions.length} vertices took a snap and are the exact stored coordinates.`
    );
  }

  // The ring check is only meaningful for a closed shape digitised from points.
  if (kind === 'polygon' && drawState.snapPointsOnly) {
    const ring = [...positions, positions[0]];
    const stranded = pointsInsideRing(ring, snapSourcesFor(item), positions);
    if (stranded > 0) {
      store.log(
        'warn',
        `${stranded} imported point${stranded === 1 ? ' is' : 's are'} inside this boundary but was not clicked. ` +
          'That usually means a corner was missed and the ring closed early — but a point genuinely inside a parcel is also normal, so nothing was changed.'
      );
    }
  }
  host.render();
}

/** The layers a drawn vertex may snap to, honouring the digitising mode. */
function snapSourcesFor(item: QueueItem): SnapSource[] {
  const sources: SnapSource[] = selectableLayers(item).map((layer) => ({
    name: layer.name,
    features: layer.features,
    // A hidden layer is not a snap target: snapping to something invisible
    // moves a vertex somewhere the user cannot see and did not ask for. A
    // LOCKED one is fine — locking stops it being edited, not being measured
    // from, and a control layer is usually locked on purpose.
    usable: layer.visible !== false,
  }));
  return drawState.snapPointsOnly ? pointSnapSources(sources) : sources;
}

/**
 * What one clicked feature is: its area, its perimeter, its vertex count.
 *
 * Phase E. Every number here comes from `core/measure.ts`, which picks geodesic
 * or planar arithmetic from the CRS and SAYS WHICH — the same engine the
 * measuring tool and the vertex readout use. A second area calculation living
 * in a panel is how two parts of one tool come to disagree about the same
 * parcel, and the one the user believes is whichever they saw last.
 *
 * Shown only for a single feature. An aggregate over a selection would be a
 * different measurement with the same name: the "area" of forty parcels is
 * their sum only if none of them overlap, and this cannot know that.
 */
function featureInfo(item: QueueItem, selection: Selection): HTMLElement | null {
  if (selection.wholeLayers.length > 0 || selection.refs.length !== 1) return null;

  const ref = selection.refs[0];
  const layer = ((item.dataset?.layers ?? []) as any[]).find((candidate) => candidate.name === ref.layer);
  const feature = (layer?.preview ?? [])[ref.index];
  if (!feature) return null;

  const measured = measureGeometry(feature.geometry ?? null, {
    crs: item.dataset?.crs ?? null,
    units: item.dataset?.units ?? null,
  });

  const section = element('div', { class: 'section' });
  section.append(element('h3', { class: 'section__title', text: 'This feature' }));

  const rows: [string, string][] = [
    ['Layer', ref.layer],
    ['Geometry', feature.geometry?.type ?? 'none'],
  ];
  if (feature.id !== undefined) rows.push(['Id', String(feature.id)]);
  if (measured.area) rows.push(['Area', measured.area.text]);
  if (measured.perimeter) rows.push(['Perimeter', measured.perimeter.text]);
  if (measured.length) rows.push(['Length', measured.length.text]);
  rows.push(['Vertices', measured.vertices.toLocaleString()]);
  section.append(keyValues(rows));

  // The method, always. A planar area on an undeclared CRS is a number in
  // unknown units, and it looks exactly like a correct one.
  section.append(element('p', { class: 'small faint', style: 'margin-top:6px', text: METHOD_LABEL[measured.method] }));

  const properties = Object.entries(feature.properties ?? {});
  if (properties.length > 0) {
    const attributes = element('details', { class: 'small', style: 'margin-top:8px' });
    attributes.append(element('summary', { text: `${properties.length} attribute${properties.length === 1 ? '' : 's'}` }));
    attributes.append(keyValues(properties.map(([key, value]) => [key, formatValue(value)] as [string, string])));
    section.append(attributes);
  }

  return section;
}

/**
 * Creates the tool layer the first time the tab is opened, and re-claims the
 * canvas's single overlay hook on every render.
 */
export function renderSelect(item: QueueItem): void {
  if (!ui.previewCanvas) return;

  if (!ui.toolCanvas) {
    ui.toolCanvas = new ToolCanvas(ui.previewCanvas, {
      layers: () => {
        const current = store.selected();
        return current ? selectableLayers(current) : [];
      },
      selection: () => ui.featureSelection,
      // A right-click that did not drag opens the canvas menu. The band owns
      // the right button while it is being dragged; this is the other case.
      onContextMenu: (screenX, screenY, world) => openCanvasMenu(screenX, screenY, { x: world[0], y: world[1] }),
      onSelectionChange: (selection) => {
        ui.featureSelection = selection;
        // `render`, not `renderInspector`: a feature selection is read by more
        // than the Select panel — the attribute table annotates its header with
        // the count, and the toolbar enables the tools that need something
        // selected. Refreshing only the inspector left those disagreeing with
        // what was highlighted on the canvas.
        host.render();
      },
      onMove: (selection, offset) => commitMove(selection, offset),
      onStatus: (text) => {
        const readout = document.getElementById('selectStatus');
        if (readout) readout.textContent = text;
      },
      onToolChange: () => host.renderInspector(),
      onDraw: (kind, positions, snaps) => commitDrawing(kind, positions, snaps),
      snapSources: () => {
        const current = store.selected();
        return current ? snapSourcesFor(current) : [];
      },
      // The toolbar's Snap button is the master switch; the three checkboxes in
      // the drawing section choose WHICH snaps apply when it is on. Before this
      // they were the only control, four clicks into the dock, so a user who
      // turned "Snap" on at the canvas and saw nothing snap was reading a
      // button that governed a different setting.
      snapSettings: (): SnapSettings =>
        ui.snapOn === false
          ? { ...DEFAULT_SNAP_SETTINGS, vertex: false, midpoint: false, segment: false }
          : {
              ...DEFAULT_SNAP_SETTINGS,
              vertex: drawState.snapVertex,
              midpoint: drawState.snapMidpoint,
              segment: drawState.snapSegment,
            },
    });
  }

  void item;
  ui.toolCanvas.reattach();
  ui.toolCanvas.setEnabled(true);
}

/**
 * Turns a completed drag into replayable translate commands.
 *
 * One per layer, as the header explains. A zero-length move is discarded rather
 * than recorded: a drag that snapped back to where it started is not an edit,
 * and an undo history full of no-ops makes the real entries hard to find.
 */
function commitMove(selection: Selection, offset: { dx: number; dy: number }): void {
  const item = store.selected();
  if (!item) return;

  if (offset.dx === 0 && offset.dy === 0) return;

  const names = selectedLayers(selection);
  if (names.length === 0) {
    store.log('warn', 'Nothing was selected, so nothing moved.');
    host.render();
    return;
  }

  const data = datasetForTools(item);
  const protectedLayers = protectedFor(item);
  let applied = 0;

  for (const layer of names) {
    const scope = scopeFor(selection, layer);
    if (scope === null) continue;

    const options = { offset: [offset.dx, offset.dy] as [number, number], ...(scope ? { scope } : {}) };
    const plan = planGeometryOperation(data, layer, 'translate', {
      ...options,
      protectedLayers,
      crs: item.dataset?.crs ?? null,
    });

    if (plan.refusal) {
      store.log('warn', `${layer}: ${plan.refusal.what} ${plan.refusal.why} ${plan.refusal.action}`);
      continue;
    }

    // Each command is queued against the item as the store now holds it, so a
    // second layer's plan is computed against the first layer's result rather
    // than against a stale copy.
    const current = store.selected();
    if (!current) return;
    queueEdit(
      current,
      { kind: 'geometry', layer, operation: 'translate', options },
      plan,
      `Move ${layer} by ${offset.dx.toFixed(3)}, ${offset.dy.toFixed(3)}`
    );
    applied += 1;
  }

  if (applied === 0) {
    host.render();
    return;
  }
  store.log(
    'ok',
    `Moved ${applied} layer${applied === 1 ? '' : 's'} by ${offset.dx.toFixed(3)}, ${offset.dy.toFixed(3)}. ` +
      'The offset is recorded and re-applied to every feature when you convert.'
  );
  host.render();
}

/**
 * The layers as the canvas draws them, carrying lock and visibility.
 *
 * Both matter to selection, not only to drawing: a hidden layer cannot be
 * clicked because the user cannot see what they would be picking, and a locked
 * one cannot be selected because every edit would refuse anyway — and a
 * selection that cannot be acted on is worse than no selection, since it looks
 * like the tool is working.
 */
export function selectableLayers(item: QueueItem): SelectableLayer[] {
  const view = viewOf(item);
  const protectedNames = new Set(store.get().settings.protectedLayers ?? []);
  return ((item.dataset?.layers ?? []) as any[]).map((layer) => ({
    name: layer.name,
    features: layer.preview ?? [],
    truncated: layer.previewTruncated === true,
    featureCount: layer.featureCount ?? (layer.preview ?? []).length,
    locked: isLocked(view, layer.name) || protectedNames.has(layer.name),
    visible: isVisible(view, layer.name),
  }));
}

/**
 * Fills the canvas with whatever is selected.
 *
 * Exported because the canvas's right-click menu offers the same thing, and a
 * second implementation there would be a second idea of how much margin to
 * leave — which is exactly how two controls with one label come to frame a
 * parcel differently.
 */
export function zoomToSelection(): void {
  const item = store.selected();
  if (!item) return;
  const bounds = selectionBounds(ui.featureSelection, selectableLayers(item));
  if (!bounds) {
    store.log('warn', 'Nothing is selected, so there is nothing to zoom to.');
    host.render();
    return;
  }
  ui.previewCanvas?.setView({
    // A little wider than the selection itself, so its edges are visible
    // rather than flush against the frame.
    scale: viewScaleFor(bounds),
    centreX: (bounds.minX + bounds.maxX) / 2,
    centreY: (bounds.minY + bounds.maxY) / 2,
  });
}

function setSelection(selection: Selection): void {
  ui.featureSelection = selection;
  host.render();
}

/** A scale that fits the bounds with a margin, for zoom-to-selection. */
function viewScaleFor(bounds: { minX: number; minY: number; maxX: number; maxY: number }): number {
  const element = document.getElementById('previewCanvas');
  const width = element?.clientWidth || 800;
  const height = element?.clientHeight || 400;
  const spanX = Math.max(bounds.maxX - bounds.minX, 1e-9);
  const spanY = Math.max(bounds.maxY - bounds.minY, 1e-9);
  return Math.min((width - 80) / spanX, (height - 80) / spanY);
}

/** The status line the tool writes into while a gesture is in progress. */
export function selectStatusBar(): HTMLElement {
  return element('div', { class: 'toolbar__status', id: 'selectStatus', text: 'Nothing selected' });
}

/** Exported for the tests: the anchor a transform would use by default. */
export function defaultAnchor(selection: Selection, layers: SelectableLayer[]): Position | null {
  const bounds = selectionBounds(selection, layers);
  return bounds ? [(bounds.minX + bounds.maxX) / 2, (bounds.minY + bounds.maxY) / 2] : null;
}
